function prefsWithManualProvider(): PreferencesStore {
	const prefs = new PreferencesStore(path.resolve("/memfs/title-direct"), createMemFs());
	prefs.set("customProviders", [{
		id: "direct",
		name: "direct",
		type: "manual",
		baseUrl: "http://127.0.0.1:9",
		apiKey: "sk-test",
		models: [{ id: "direct-title-model", name: "Direct Title Model" }],
	}]);
	return prefs;
}

describe("title generation with non-AI-Gateway naming models", () => {
	it("uses the configured direct naming model and forces thinking off", async () => {
		delete process.env.BOBBIT_SKIP_TITLE_GEN;
		const calls: any[] = [];
		const title = await generateSessionTitle(
			[{ role: "user", content: "Please fix the direct model title path." }],
			{
				namingModel: "direct/direct-title-model",
				thinkingLevel: "high",
				availableModels: [directModel],
				directModelCompleter: async (model, args) => {
					calls.push({ model, args });
					return "<title>Direct Works</title>";
				},
			},
		);
		assert.equal(title, "Direct Works");
		assert.equal(calls.length, 1);
		assert.equal(calls[0].model.provider, "direct");
		assert.equal(calls[0].model.id, "direct-title-model");
		assert.equal(calls[0].args.thinkingLevel, "off");
	});

	it("redacts configured naming-model completion errors before logging", async () => {
		const sentinel = `secret-${"x".repeat(48)}`;
		const originalError = console.error;
		const lines: string[] = [];
		console.error = (...args: unknown[]) => lines.push(args.map(String).join(" "));
		try {
			assert.equal(await generateSessionTitle(
				[{ role: "user", content: "Keep configured naming-model errors private." }],
				{
					namingModel: "direct/direct-title-model",
					availableModels: [directModel],
					directModelCompleter: async () => { throw new Error(`Authorization: Bearer ${sentinel}`); },
				},
			), null);
			assert.equal(lines.join("\n").includes(sentinel), false);
			assert.match(lines.join("\n"), /<redacted-token>/);
		} finally {
			console.error = originalError;
		}
	});

	it("keeps explicit Anthropic naming direct when AIGW-exclusive models hide built-ins", async () => {
		const dir = mkdtempSync(path.join(tmpdir(), "bobbit-title-anthropic-"));
		process.env.BOBBIT_AGENT_DIR = dir;
		resetAgentDirStateForTests();
		writeFileSync(path.join(dir, "auth.json"), JSON.stringify({ anthropic: { type: "api-key", key: "anthropic-test-key" } }));
		const requests: any[] = [];
		const fetchImpl = (async (_input: any, init?: RequestInit) => {
			requests.push(JSON.parse(String(init?.body)));
			return new Response(JSON.stringify({ content: [{ type: "text", text: "<title>Direct Anthropic</title>" }] }), {
				status: 200,
				headers: { "Content-Type": "application/json" },
			});
		}) as typeof fetch;
		try {
			const options = {
				namingModel: "anthropic/claude-explicit",
				aigwUrl: "http://127.0.0.1:1",
				availableModels: [],
				fetchImpl,
			};
			assert.equal(await generateSessionTitle([{ role: "user", content: "Keep my model" }], options), "Direct Anthropic");
			assert.equal(await generateGoalSummaryTitle("Keep explicit naming model", options), "Direct Anthropic");
			assert.deepEqual(requests.map((body) => body.model), ["claude-explicit", "claude-explicit"]);
		} finally {
			rmSync(dir, { recursive: true, force: true });
		}
	});

	it("uses the session model as fallback when no naming model is set", async () => {
		delete process.env.BOBBIT_SKIP_TITLE_GEN;
		const calls: any[] = [];
		const title = await generateSessionTitle(
			[{ role: "user", content: "Please diagnose why automatic names stopped changing." }],
			{
				fallbackModel: "openai-codex/direct-title-model",
				availableModels: [{ ...directModel, provider: "openai-codex" }],
				directModelCompleter: async (model, args) => {
					calls.push({ model, args });
					return "<title>Rename Diagnosis</title>";
				},
			},
		);
		assert.equal(title, "Rename Diagnosis");
		assert.equal(calls.length, 1);
		assert.equal(calls[0].model.provider, "openai-codex");
		assert.equal(calls[0].args.thinkingLevel, "off");
	});

	it("keeps anonymous gateway completions usable and scopes named credentials at completion time", async () => {
		const prefs = new PreferencesStore(path.resolve("/memfs/title-gateway"), createMemFs());
		const gateway = { id: "title-gateway", name: "title-gateway", url: "http://127.0.0.1:9", type: "openai-compatible" as const, enabled: true };
		prefs.set("modelGateways", [gateway]);
		const model = { ...directModel, provider: gateway.name };
		const seen: Array<string | undefined> = [];
		const complete = async (_model: any, _context: any, options: any) => {
			seen.push(options.apiKey);
			return { role: "assistant", content: [{ type: "text", text: "OK" }], stopReason: "stop" } as any;
		};
		const dependencies = {
			env: { TITLE_GATEWAY_TOKEN: "from-env" },
			commandRunner: { async execFile() { return { stdout: "from-command", stderr: "" }; } },
		};
		for (const [expression, expected] of [[undefined, "none"], ["none", "none"], ["literal-token", "literal-token"], ["TITLE_GATEWAY_TOKEN", "from-env"], ["!echo token", "from-command"]] as const) {
			if (expression === undefined) prefs.remove(`providerKey.gateway.${gateway.id}`);
			else prefs.set(`providerKey.gateway.${gateway.id}`, expression);
			await completeModelText(model, prefs, { systemPrompt: "test", userPrompt: "test" }, complete, dependencies);
			assert.equal(seen.pop(), expected);
		}

		prefs.set(`providerKey.gateway.${gateway.id}`, "literal-token");
		await completeModelText(
			{ ...model, baseUrl: "http://127.0.0.1:10/v1" },
			prefs,
			{ systemPrompt: "test", userPrompt: "test" },
			complete,
			dependencies,
		);
		assert.equal(seen.pop(), "none", "a retained foreign endpoint must not receive the gateway credential");

		prefs.set(`providerKey.gateway.${gateway.id}`, "!failing-command");
		const beforeFailure = seen.length;
		await assert.rejects(
			completeModelText(model, prefs, { systemPrompt: "test", userPrompt: "test" }, complete, {
				commandRunner: { async execFile() { throw new Error("credential output must not leak"); } },
			}),
			GatewayCredentialResolutionError,
		);
		assert.equal(seen.length, beforeFailure, "a failed gateway key command must make zero completion calls");

		// A configured expression is still authoritative for a retained foreign
		// endpoint: resolution failures must stop the request rather than letting
		// the cross-origin no-bearer path become an anonymous fallback.
		for (const [label, rejects] of [["rejecting", true], ["empty", false]] as const) {
			let commandCalls = 0;
			const beforeForeignFailure = seen.length;
			await assert.rejects(
				completeModelText(
					{ ...model, baseUrl: "http://127.0.0.1:10/v1" },
					prefs,
					{ systemPrompt: "test", userPrompt: "test" },
					complete,
					{ commandRunner: { async execFile() {
						commandCalls++;
						if (rejects) throw new Error("credential output must not leak");
						return { stdout: " \n", stderr: "" };
					} } },
				),
				GatewayCredentialResolutionError,
			);
			assert.equal(commandCalls, 1, `${label} command must resolve before origin gating`);
			assert.equal(seen.length, beforeForeignFailure, `${label} command failure must make zero completion/receiver requests`);
		}
	});

	it("model completions reuse OpenAI Codex OAuth credentials, matching chat auth", async () => {
		const dir = mkdtempSync(path.join(tmpdir(), "bobbit-title-auth-"));
		process.env.BOBBIT_AGENT_DIR = dir;
		// Re-point the cached agent-dir runtime singleton at this test's dir so
		// completeModelText resolves auth.json (via globalAuthPath()) under it.
		resetAgentDirStateForTests();
		writeFileSync(path.join(dir, "auth.json"), JSON.stringify({ "openai-codex": { type: "oauth", access: "codex-oauth-token" } }));
		// Ambient OPENAI_API_KEY would short-circuit resolveProviderApiKey before auth.json, masking the OAuth-credential path under test.
		const prevOpenAiKey = process.env.OPENAI_API_KEY;
		delete process.env.OPENAI_API_KEY;
		const calls: any[] = [];
		try {
			await completeModelText({ ...directModel, provider: "openai-codex", api: "openai-codex-responses" }, undefined, {
				systemPrompt: "test",
				userPrompt: "test",
			}, async (model, _context, options) => {
				calls.push({ model, options });
				return { role: "assistant", content: [{ type: "text", text: "OK" }], stopReason: "stop" } as any;
			});
			assert.equal(calls[0].options.apiKey, "codex-oauth-token");
		} finally {
			if (prevOpenAiKey === undefined) delete process.env.OPENAI_API_KEY;
			else process.env.OPENAI_API_KEY = prevOpenAiKey;
			rmSync(dir, { recursive: true, force: true });
		}
	});

	it("model test helper works for non-AI-Gateway models", async () => {
		const prefs = prefsWithManualProvider();
		const calls: any[] = [];
		const result = await testModelPreference(prefs, "direct/direct-title-model", async (model, _prefs, args) => {
			calls.push({ model, args });
			return "OK";
		});
		assert.equal(result.ok, true);
		assert.equal(result.modelResolved, "direct-title-model");
		assert.equal(calls.length, 1);
		assert.equal(calls[0].model.provider, "direct");
		assert.equal(calls[0].model.id, "direct-title-model");
		assert.equal(calls[0].args.thinkingLevel, "off");
	});
});
